/**
 * Home.jsx
 * Main landing page with real-time clock display
 */

import React, { useState, useEffect } from 'react';
import { Home as HomeIcon, Clock } from 'lucide-react';

const Home = () => {
  const [currentTime, setCurrentTime] = useState(new Date());

  useEffect(() => {
    // Update time immediately on mount
    setCurrentTime(new Date());

    // Set up interval to update every second
    const timeInterval = setInterval(() => {
      setCurrentTime(new Date());
    }, 1000);

    // Cleanup interval on component unmount
    return () => {
      clearInterval(timeInterval);
    };
  }, []);

  // Format time in 24-hour format (HH:MM:SS)
  const formatTime = (date) => {
    return date.toLocaleTimeString('en-US', {
      hour12: false,
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  };

  // Get the user's timezone in IANA format
  const getTimeZone = () => {
    return Intl.DateTimeFormat().resolvedOptions().timeZone;
  };

  // Get current date in a readable format
  const formatDate = (date) => {
    return date.toLocaleDateString('en-US', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  return (
    <div className="space-y-8">
      {/* Welcome Header */}
      <div className="flex items-center space-x-3">
        <HomeIcon className="w-8 h-8 text-blue-600" />
        <h1 className="text-3xl font-bold">Welcome</h1>
      </div>

      {/* Real-time Clock Section */}
      <div className="flex justify-center">
        <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg border border-gray-200 dark:border-gray-700 p-8 max-w-md w-full">
          {/* Clock Icon Header */}
          <div className="flex justify-center mb-6">
            <div className="p-3 bg-blue-100 dark:bg-blue-900/30 rounded-full">
              <Clock className="w-8 h-8 text-blue-600" />
            </div>
          </div>

          {/* Current Date */}
          <div className="text-center mb-4">
            <p className="text-lg font-medium text-gray-700 dark:text-gray-300">
              {formatDate(currentTime)}
            </p>
          </div>

          {/* Current Time Display */}
          <div className="text-center mb-6">
            <div className="text-5xl font-mono font-bold text-gray-900 dark:text-white tracking-wider">
              {formatTime(currentTime)}
            </div>
          </div>

          {/* Time Zone Display */}
          <div className="text-center">
            <div className="inline-flex items-center space-x-2 px-4 py-2 bg-gray-100 dark:bg-gray-700 rounded-lg">
              <span className="text-sm font-medium text-gray-600 dark:text-gray-400">
                Time Zone:
              </span>
              <span className="text-sm font-semibold text-gray-800 dark:text-gray-200">
                {getTimeZone()}
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Home;
